fs.disk-status.ps1:
foreach ($s in Get-Content .\servers.txt) {
  $d = Get-CimInstance Win32_LogicalDisk -ComputerName $s -Filter "DeviceID='C:'"
  $pct = [math]::Round($d.FreeSpace / $d.Size * 100, 1)
  $st = if ($pct -lt 15) {'LOW'} elseif ($pct -lt 25) {'WATCH'} else {'OK'}
  [pscustomobject]@{Server=$s; FreePct=$pct; Status=$st}
}

