function Get-LowDisk {
  [CmdletBinding()]
  param([Parameter(Mandatory)][string[]]$ComputerName, [int]$Threshold = 15)
  foreach ($c in $ComputerName) {
    try {
      $d = Get-CimInstance Win32_LogicalDisk -ComputerName $c -Filter "DeviceID='C:'" -ErrorAction Stop
      $pct = [math]::Round($d.FreeSpace/$d.Size*100,1)
      if ($pct -lt $Threshold) { [pscustomobject]@{Server=$c; FreePct=$pct} }
    } catch { Write-Warning "$c unreachable: $($_.Exception.Message)" }
  }
}
